+func validatePerformanceOperationRequest(req OperationRequest) error {
+	switch req.Kind {
+	case OperationPerformanceDryRun, OperationPerformanceStart, OperationPerformanceStatus, OperationPerformanceEvidence, OperationPerformanceResume, OperationPerformanceRecover, OperationPerformanceCancel:
+	default:
+		return nil
+	}
+	if req.Project == "" || req.Sprint == "" || req.Study != "" || req.Stage != "" || req.Task != "" || req.Model != "" || req.Level != "" || req.Suite != "" || req.Test != "" || req.Timeout != "" || req.ForceReview || req.RestartReview || req.OverrideRationale != "" || len(req.ReviewFocus) > 0 || len(req.Sources) > 0 || len(req.Dimensions) > 0 || req.Parallelism != 0 {
+		return fmt.Errorf("performance operations accept only project and sprint")
+	}
+	if req.Kind == OperationPerformanceEvidence {
+		if len(req.Cursor) > 1024 || len(req.Filter) > 64 || strings.ContainsAny(req.Filter, "\x00/\\") || req.Limit < 0 || req.Limit > sprint.MaxPerformanceLimits().EvidencePageSize {
+			return fmt.Errorf("performance evidence query is outside its bounded cursor, filter, or page limit")
+		}
+	} else if req.Cursor != "" || req.Filter != "" || req.Limit != 0 {
+		return fmt.Errorf("performance cursor, filter, and limit apply only to evidence queries")
+	}
+	return nil
+}
