index 0000000000000000000000000000000000000000..3b455b6bf5ea5d690f896938c087670f93b20aaa
--- /dev/null
+++ b/internal/app/performance_fixtures_test.go
@@ -0,0 +1,43 @@
+package app
+
+import (
+	"encoding/json"
+	"os"
+	"path/filepath"
+	"testing"
+)
+
+func TestCanonicalPerformanceFixtureFamilyCoversEveryPresentationState(t *testing.T) {
+	path := filepath.Join("..", "testdata", "performance", "states.json")
+	data, err := os.ReadFile(path)
+	if err != nil {
+		t.Fatal(err)
+	}
+	var family struct {
+		SchemaVersion int `json:"schema_version"`
+		States        []struct {
+			Name      string `json:"name"`
+			Enabled   bool   `json:"enabled"`
+			Phase     string `json:"phase"`
+			Fresh     bool   `json:"fresh"`
+			Outcome   string `json:"outcome"`
+			Lifecycle string `json:"operational_lifecycle"`
+		} `json:"states"`
+	}
+	if err := json.Unmarshal(data, &family); err != nil {
+		t.Fatal(err)
+	}
+	want := []string{"disabled", "ready", "preparing", "active", "cancelling", "passed", "passed-with-reports", "target-missed", "blocked", "cancelled", "cleanup-uncertain", "stalled", "stale", "interrupted-resumable", "historical", "evidence-gap", "recovery-conflict"}
+	seen := map[string]bool{}
+	for _, state := range family.States {
+		if seen[state.Name] || state.Name == "" || state.Phase == "" {
+			t.Fatalf("invalid fixture %#v", state)
+		}
+		seen[state.Name] = true
+	}
+	for _, name := range want {
+		if !seen[name] {
+			t.Fatalf("missing canonical performance fixture %q", name)
+		}
+	}
+}

