+package project
+
+import "testing"
+
+func TestPerformancePolicyParsing(t *testing.T) {
+	tests := []struct {
+		name     string
+		content  string
+		mode     PerformanceMode
+		findings bool
+	}{
+		{name: "missing defaults disabled", content: "# Project\n", mode: PerformanceDisabled},
+		{name: "disabled", content: "## Performance Policy\n\n- **Mode:** disabled\n", mode: PerformanceDisabled},
+		{name: "enabled", content: "## Performance Policy\n\n- **Mode:** enabled\n", mode: PerformanceEnabled},
+		{name: "duplicate section", content: "## Performance Policy\n- **Mode:** enabled\n## Performance Policy\n- **Mode:** enabled\n", mode: PerformanceEnabled, findings: true},
+		{name: "duplicate key", content: "## Performance Policy\n- **Mode:** enabled\n- **Mode:** disabled\n", mode: PerformanceEnabled, findings: true},
+		{name: "unknown key", content: "## Performance Policy\n- **Mode:** enabled\n- **Samples:** 10\n", mode: PerformanceEnabled, findings: true},
+		{name: "invalid mode", content: "## Performance Policy\n- **Mode:** fast\n", mode: PerformanceDisabled, findings: true},
+		{name: "fenced pseudo section", content: "```md\n## Performance Policy\n- **Mode:** enabled\n```\n", mode: PerformanceDisabled},
+		{name: "quoted pseudo section", content: "> ## Performance Policy\n> - **Mode:** enabled\n", mode: PerformanceDisabled},
+		{name: "commented pseudo section", content: "<!--\n## Performance Policy\n- **Mode:** enabled\n-->\n", mode: PerformanceDisabled},
+	}
+	for _, test := range tests {
+		t.Run(test.name, func(t *testing.T) {
+			index, findings := ParseProjectIndex(test.content)
+			if index.PerformancePolicy.Mode != test.mode {
+				t.Fatalf("mode = %q, want %q", index.PerformancePolicy.Mode, test.mode)
+			}
+			if (len(findings) > 0) != test.findings {
+				t.Fatalf("findings = %#v", findings)
+			}
+			if len(index.PerformancePolicy.SourceDigest) != 64 {
+				t.Fatalf("source digest = %q", index.PerformancePolicy.SourceDigest)
+			}
+		})
+	}
+}

