+)
+
+const performanceAuthoringPrompt = `You are authoring measurement-only Go test code for requirements-owned performance targets.
+Work only in the isolated repository copy. Add new *_test.go measurement files and, only when needed, new package-local testdata/performance files. Do not alter existing files. Every measurement function must have an immediately preceding marker in this exact form:
+// ultraplan:performance-v1 <go-benchmark-v1|ultraplan-json-v1> <raw-unit> <comma-separated-target-ids>
+Use Benchmark... symbols for Go benchmark units and Test... symbols emitting exactly one ULTRAPLAN_PERFORMANCE_V1 JSON envelope for other raw units. Do not modify production, existing tests, assertions, expected output, fixtures, configuration, governance, evidence, repository controls, or Git data. Do not run shell or Git commands. Product code validates coverage and runs correctness checks before promotion.
+
+Frozen target packet:
+`
+
+// PreparePerformanceManifest discovers a complete existing manifest or runs a
+// bounded measurement-only authoring proposal in a disposable copy. Promotion
+// is restricted to newly created test measurement files and data.
+func (s Service) PreparePerformanceManifest(ctx context.Context, projectRef, sprintRef string, prepared PerformancePrepareResult, env []string, acceptedAt time.Time, token VerificationWriterToken) (PerformanceBenchmarkManifest, int, error) {
+	if manifest, err := DiscoverPerformanceManifest(prepared.Target.Path, prepared.Packet); err == nil {
+		return manifest, 0, nil
+	}
+	if s.runtime == nil {
+		return PerformanceBenchmarkManifest{}, 0, fmt.Errorf("benchmark coverage is incomplete and no performance authoring runtime is configured")
+	}
+	if acceptedAt.IsZero() {
+		acceptedAt = s.now().UTC()
+	}
+	var cancel context.CancelFunc
+	ctx, cancel = context.WithDeadline(ctx, acceptedAt.Add(prepared.Limits.WallTime))
+	defer cancel()
+	lockedCtx, release, err := s.acquireMutationContext(ctx, projectRef, sprintRef)
+	if err != nil {
+		return PerformanceBenchmarkManifest{}, 0, err
+	}
+	defer release()
+	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
+	if err != nil {
+		return PerformanceBenchmarkManifest{}, 0, err
+	}
+	if err := NewPerformanceStore(s.root, sp).WithWriterFence(s.verificationWriterFence).checkWriter(token); err != nil {
+		return PerformanceBenchmarkManifest{}, 0, err
+	}
+	initial, err := targetIdentity(prepared.Target.Path)
+	if err != nil {
+		return PerformanceBenchmarkManifest{}, 0, err
+	}
+	packetJSON, _ := jsonCanonical(prepared.Packet)
+	var lastErr error
+	for attempt := 1; attempt <= prepared.Limits.AuthoringAttempts; attempt++ {
+		isolation, isolateErr := createPerformanceIsolation(lockedCtx, prepared.Target.Path, prepared.ProtectedRoots, prepared.Limits)
+		if isolateErr != nil {
+			return PerformanceBenchmarkManifest{}, attempt - 1, isolateErr
+		}
+		request := s.runtimeRequest(performanceAuthoringPrompt+string(packetJSON), map[string]string{"project": prepared.Project, "sprint": prepared.Sprint, "stage": string(VerificationPhasePerformance), "operation": "performance-benchmark-authoring", "attempt": fmt.Sprint(attempt)})
+		if override, ok := s.verificationRuntime[VerificationPhasePerformance]; ok {
+			request.Provider, request.Model = splitProviderModel(override.Model)
+			request.Metadata["variant"] = override.Variant
+		}
+		request.WorkDir, request.Timeout, request.Sandbox, request.Permissions = isolation.workspace.Path, prepared.Limits.WallTime, "workspace_write", "restricted"
+		request.Policy.Default 

[... bounded excerpt ...]

ed.Limits, env)
+				}
+				if compareErr == nil && discoverErr == nil {
+					current, identityErr := targetIdentity(prepared.Target.Path)
+					if identityErr != nil || current != initial {
+						compareErr = fmt.Errorf("canonical source changed before benchmark promotion")
+					} else {
+						compareErr = promotePerformanceAuthoring(prepared.Target.Path, isolation.workspace.Path, changed, prepared.Limits)
+					}
+					if compareErr == nil {
+						candidate, compareErr = DiscoverPerformanceManifest(prepared.Target.Path, prepared.Packet)
+					}
+					cleanupErr := isolation.cleanup()
+					if cleanupErr != nil {
+						return PerformanceBenchmarkManifest{}, attempt, cleanupErr
+					}
+					if compareErr == nil {
+						return candidate, attempt, nil
+					}
+				}
+				lastErr = errors.Join(discoverErr, compareErr)
+			} else {
+				lastErr = compareErr
+			}
+		} else {
+			lastErr = runErr
+		}
+		if cleanupErr := isolation.cleanup(); cleanupErr != nil {
+			return PerformanceBenchmarkManifest{}, attempt, errors.Join(lastErr, cleanupErr)
+		}
+	}
+	return PerformanceBenchmarkManifest{}, prepared.Limits.AuthoringAttempts, fmt.Errorf("bounded benchmark authoring exhausted: %w", lastErr)
+}
+
+func validatePerformanceAuthoringChanges(canonical, isolated string, paths []string, limits PerformanceLimits) error {
+	if len(paths) == 0 || len(paths) > limits.ChangedFiles {
+		return fmt.Errorf("benchmark proposal has no bounded changed files")
+	}
+	var bytesChanged int64
+	for _, rel := range paths {
+		normalized, err := normalizeRepairPath(rel)
+		if err != nil || normalized != rel {
+			return fmt.Errorf("unsafe benchmark path %q", rel)
+		}
+		lower := strings.ToLower(normalized)
+		if !strings.HasSuffix(lower, "_test.go") && !strings.Contains(lower, "/testdata/performance/") && !strings.HasPrefix(lower, "testdata/performance/") {
+			return fmt.Errorf("benchmark proposal changed protected path %q", rel)
+		}
+		if _, err := os.Lstat(filepath.Join(canonical, filepath.FromSlash(rel))); !errors.Is(err, fs.ErrNotExist) {
+			return fmt.Errorf("benchmark authoring cannot alter an existing file %q", rel)
+		}
+		path := filepath.Join(isolated, filepath.FromSlash(rel))
+		info, err := os.Lstat(path)
+		if err != nil || !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0 {
+			return fmt.Errorf("benchmark proposal file is unsafe %q", rel)
+		}
+		if err := ensureRepairRegularPath(isolated, path); err != nil {
+			return fmt.Errorf("benchmark proposal file is linked or unsafe %q: %w", rel, err)
+		}
+		if info.Mode().Perm()&0111 != 0 {
+			return fmt.Errorf("benchmark proposal file is executable %q", rel)
+		}
+		bytesChanged += info.Size()
+		if bytesChanged > limits.ChangedBytes {
+			return fmt.Errorf("benchmark proposal exceeds changed-byte limit")
+		}
+	}
+	return nil
+}
+
+func runPerformanceAuthoringChecks(ctx context.Context, runner pprocess.Runner, root string, commands [][]string, limits PerformanceLimits, env []string) error {
+	if runner == nil {
+		runner = pprocess.DirectRunner{}
+	}
+	counters := PerformanceCounters{}
+	return runPerformanceCorrectness(ctx, runner, root, commands, limits, env, &counters)
+}
+
+func promotePerformanceAuthoring(canonical, isolated string, paths []string, limits PerformanceLimits) error {
+	sort.Strings(paths)
+	created := []string{}
+	for _, rel := range paths {
+		source := filepath.Join(isolated, filepath.FromSlash(rel))
+		content, err := os.ReadFile(source)
+		if err != nil {
+			return err
+		}
+		destination := filepath.Join(canonical, filepath.FromSlash(rel))
+		if err := ensureRepairCreatablePath(canonical, destination); err != nil {
+			return err
+		}
+		if err := privateAtomicWrite(destination, content, "performance-benchmark-promote", QAStateHooks{}); err != nil {
+			for i := len(created) - 1; i >= 0; i-- {
+				_ = os.Remove(filepath.Join(canonical, filepath.FromSlash(created[i])))
+			}
+			return err
+		}
+		created = append(created, rel)
+	}
+	return nil
+}
+
+func jsonCanonical(value any) ([]byte, error) { return json.Marshal(value) }

diff --git a/internal/sprint/performance_benchmark.go b/internal/sprint/performance_benchmark.go
new file mode 100644
index 0000000000000000000000000000000000000000..93b7cec6625b6dec83e2e02fddbea1bb9312dc6a
--- /dev/null
+++ b/internal/sprint/performance_benchmark.go
@@ -0,0 +1,172 @@
+package sprint
+
+import (
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"fmt"
+	"path/filepath"
+	"regexp"
+	"sort"
+	"strings"
+
+	pprocess "github.com/Antonio7098/ultraplan-go/internal/platform/process"
+)
+
+const PerformanceRunnerVersion = "performance-runner-v1"
+
+var goBenchmarkSymbol = regexp.MustCompile(`^Benchmark[A-Za-z0-9_]+$`)
+var jsonPerformanceSymbol = regexp.MustCompile(`^Test[A-Za-z0-9_]+$`)
+var packageLocator = regexp.MustCompile(`^(?:\.|[A-Za-z0-9_][A-Za-z0-9_.-]*)(?:/[A-Za-z0-9_][A-Za-z0-9_.-]*)*$`)
+
+func ValidatePerformanceManifest(packet PerformanceTargetPacket, manifest *PerformanceBenchmarkManifest) error {
+	if manifest == nil {
+		return fmt.Errorf("benchmark manifest is required")
+	}
+	if manifest.SchemaVersion != PerformanceSchemaVersion || manifest.PacketDigest != packet.PacketDigest || manifest.RunnerVersion != PerformanceRunnerVersion || manifest.ParserVersion != PerformanceParserVersion {
+		return fmt.Errorf("benchmark manifest identity does not match the frozen target packet")
+	}
+	targets := make(map[string]PerformanceTarget, len(packet.Targets))
+	for _, target := range packet.Targets {
+		targets[target.ID] = target
+	}
+	covered := map[string]bool{}
+	outputs := map[string]bool{}
+	for i := range manifest.Descriptors {
+		descriptor := &manifest.Descriptors[i]
+		if err := ValidatePerformanceDescriptor(*descriptor); err != nil {
+			return fmt.Errorf("descriptor %d: %w", i+1, err)
+		}
+		if outputs[descriptor.OutputIdentity] {
+			return fmt.Errorf("duplicate output identity %q", descriptor.OutputIdentity)
+		}
+		outputs[descriptor.OutputIdentity] = true
+		for _, id := range descriptor.TargetIDs {
+			target, ok := targets[id]
+			if !ok {
+				return fmt.Errorf("descriptor maps unknown target %q", id)
+			}
+			if covered[id] {
+				return fmt.Errorf("target %q has duplicate benchmark coverage", id)
+			}
+			if target.Basis != PerformanceRelative && descriptor.RawUnit != target.Unit {
+				return fmt.Errorf("target %q raw unit %q does not match %q", id, descriptor.RawUnit, target.Unit)
+			}
+			if target.Basis == PerformanceRelative && descriptor.RawUnit == PerformancePercent {
+				return fmt.Errorf("target %q baseline comparison requires a non-percent raw unit", id)
+			}
+			covered[id] = true
+		}
+	}
+	if len(covered) != len(targets) {
+		return fmt.Errorf("benchmark coverage is incomplete: covered %d of %d targets", len(covered), len(targets))
+	}
+	manifest.CoverageComplete = true
+	wantDigest := performanceManifestDigest(*manifest)
+	if manifest.BenchmarkDigest != "" && manifest.BenchmarkDigest != wantDigest {
+		return fmt.Errorf("benchmark manifest digest does not match its frozen descriptors")
+	}
+	manifest.BenchmarkDigest = wantDigest
+	return nil
+}
+
+func ValidatePerformanceDescriptor(descriptor PerformanceDescriptor) error {
+	if descriptor.Kind != PerformanceGoBenchmark && descriptor.Kind != PerformanceJSONRunner {
+		return fmt.Errorf("unsupported descriptor kind %q", descriptor.Kind)
+	}
+	if !packageLocator.MatchString(descriptor.Package) || filepath.IsAbs(descriptor.Package) || strings.Contains(descriptor.Package, "..") {
+		return fmt.Errorf("unsafe package locator %q", descriptor.Package)
+	}
+	if descriptor.Kind == PerformanceGoBenchmark && !goBenchmarkSymbol.MatchString(descriptor.Symbol) {
+		return fmt.Errorf("invalid Go benchmark symbol %q", descriptor.Symbol)
+	}
+	if descriptor.Kind == PerformanceJSONRunner && !jsonPerformanceSymbol.MatchString(descriptor.Symbol) {
+		return fmt.Errorf("invalid JSON runner symbol %q", descriptor.Symbol)
+	}
+	if len(descriptor.TargetIDs) == 0 || len(descriptor.TargetIDs) > PerformanceMaxTargets || !supportedPerformanceUnit(descriptor.RawUnit) || descriptor.RawUnit == PerformancePercent {
+		return fmt.Errorf("descriptor target mapping or raw unit is invalid")
+	}
+	if descriptor.ParserVersion != PerformanceParserVersion {
+		return fmt.Errorf("unsupported parser version %q", descriptor.ParserVersion)
+	}
+	wantOutput := string(descriptor.Kind) + ":" + descriptor.Package + ":" + descriptor.Symbol + ":" + string(descriptor.RawUnit)
+	if descriptor.OutputIdentity != wantOutput {
+		return fmt.Errorf("output identity must be %q", wantOutput)
+	}
+	sorted := append([]string(nil), descriptor.TargetIDs...)
+	sort.Strings(sorted)
+	for i, id := range sorted {
+		if !performanceTargetID.MatchString(id) || i > 0 && id == sorted[i-1] {
+			return fmt.Errorf("invalid or duplicate target ID %q", id)
+		}
+	}
+	descriptor.TargetIDs = sorted
+	return nil
+}
+
+func PerformanceProcessRequest(root string, descriptor PerformanceDescriptor, limits PerformanceLimits, env []string) (pprocess.Request, error) {
+	if err := ValidatePerformanceDescriptor(descriptor); err != nil {
+		return pprocess.Request{}, err
+	}
+	if limits.CommandTimeout <= 0 || limits.StdoutBytes <= 0 || limits.StderrBytes <= 0 || limits.CleanupReserve <= 0 {
+		return pprocess.Request{}, fmt.Errorf("performance process limits must be positive")
+	}
+	cleanRoot := filepath.Clean(root)
+	args := []string{"test", descriptor.Package, "-count=1"}
+	if descriptor.Kind == PerformanceGoBenchmark {
+		args = append(args, "-run=^$", "-bench=^"+descriptor.Symbol+"$", "-benchmem")
+	} else {
+		args = append(args, "-run=^"+descriptor.Symbol+"$", "-v")
+	}
+	return pprocess.Request{Executable: "go", Args: args, Dir: cleanRoot, Env: allowPerformanceEnvironment(env), Timeout: limits.CommandTimeout, StdoutLimit: limits.StdoutBytes, StderrLimit: limits.StderrBytes, CleanupGrace: limits.CleanupReserve}, nil
+}
+
+func PerformanceProfileRequest(root, output string, descriptor PerformanceDescriptor, kind PerformanceProfileKind, limits PerformanceLimits, env []string) (pprocess.Request, error) {
+	request, err := PerformanceProcessRequest(root, descriptor, limits, env)
+	if err != nil {
+		return request, err
+	}
+	if output == "" || !filepath.IsAbs(output) {
+		return request, fmt.Errorf("performance profile output must be absolute")
+	}
+	switch kind {
+	case PerformanceProfileCPU:
+		if descriptor.Kind != PerformanceGoBenchmark {
+			return request, fmt.Errorf("CPU profile requires a Go benchmark descriptor")
+		}
+		request.Args = append(request.Args, "-cpuprofile="+output)
+	case PerformanceProfileAllocation:
+		if descriptor.Kind != PerformanceGoBenchmark {
+			return request, fmt.Errorf("allocation profile requires a Go benchmark descriptor")
+		}
+		request.Args = append(request.Args, "-memprofile="+output, "-memprofilerate=1")
+	case PerformanceProfileMemory, PerformanceProfileWall, PerformanceProfileThroughput, PerformanceProfileCount:
+		// The closed JSON runner output is itself the bounded source profile.
+	default:
+		return request, fmt.Errorf("unsupported performance profile kind %q", kind)
+	}
+	return request, nil
+}
+
+func allowPerformanceEnvironment(env []string) []string {
+	allowed := map[string]bool{"PATH": true, "HOME": true, "TMPDIR": true, "LANG": true, "LC_ALL": true, "GOCACHE": true, "GOMODCACHE": true, "GOMAXPROCS": true}
+	result := make([]string, 0, len(env))
+	for _, entry := range env {
+		key := entry
+		if at := strings.IndexByte(entry, '='); at >= 0 {
+			key = entry[:at]
+		}
+		if allowed[key] {
+			result = append(result, entry)
+		}
+	}
+	sort.Strings(result)
+	return result
+}
+
+func performanceManifestDigest(manifest PerformanceBenchmarkManifest) string {
+	manifest.BenchmarkDigest = ""
+	data, _ := json.Marshal(manifest)
+	sum := sha256.Sum256(data)
+	return hex.EncodeToString(sum[:])
+}

