+)
+
+func TestPerformanceManifestFreezesClosedDescriptors(t *testing.T) {
+	packet, findings := ParsePerformanceTargets(validPerformanceTable)
+	if len(findings) != 0 {
+		t.Fatalf("target findings = %#v", findings)
+	}
+	manifest := PerformanceBenchmarkManifest{
+		SchemaVersion: PerformanceSchemaVersion,
+		PacketDigest:  packet.PacketDigest,
+		RunnerVersion: PerformanceRunnerVersion,
+		ParserVersion: PerformanceParserVersion,
+		Descriptors: []PerformanceDescriptor{
+			performanceDescriptor(PerformanceJSONRunner, "./internal/example", "TestLatency", PerformanceMS, "PERF-A"),
+			performanceDescriptor(PerformanceJSONRunner, "./internal/example", "TestMemory", PerformanceMiB, "PERF-REPORT"),
+			performanceDescriptor(PerformanceGoBenchmark, "./internal/example", "BenchmarkZ", PerformanceNSPerOp, "PERF-Z"),
+		},
+	}
+	if err := ValidatePerformanceManifest(packet, &manifest); err != nil {
+		t.Fatal(err)
+	}
+	if !manifest.CoverageComplete || len(manifest.BenchmarkDigest) != 64 {
+		t.Fatalf("manifest was not frozen: %#v", manifest)
+	}
+	first := manifest.BenchmarkDigest
+	if err := ValidatePerformanceManifest(packet, &manifest); err != nil || manifest.BenchmarkDigest != first {
+		t.Fatalf("manifest digest is unstable: %q, %v", manifest.BenchmarkDigest, err)
+	}
+	manifest.Descriptors[0].TargetIDs = append(manifest.Descriptors[0].TargetIDs, "PERF-Z")
+	if err := ValidatePerformanceManifest(packet, &manifest); err == nil {
+		t.Fatal("accepted duplicate target coverage")
+	}
+}
+
+func TestPerformanceProcessRequestIsProductOwned(t *testing.T) {
+	descriptor := performanceDescriptor(PerformanceGoBenchmark, "./internal/example", "BenchmarkThing", PerformanceNSPerOp, "PERF-A")
+	request, err := PerformanceProcessRequest("/tmp/contained", descriptor, DefaultPerformanceLimits(), []string{"SECRET=no", "PATH=/bin", "GOMAXPROCS=1"})
+	if err != nil {
+		t.Fatal(err)
+	}
+	wantArgs := []string{"test", "./internal/example", "-count=1", "-run=^$", "-bench=^BenchmarkThing$", "-benchmem"}
+	if request.Executable != "go" || !reflect.DeepEqual(request.Args, wantArgs) || !reflect.DeepEqual(request.Env, []string{"GOMAXPROCS=1", "PATH=/bin"}) {
+		t.Fatalf("request = %#v", request)
+	}
+}
+
+func TestPerformanceOutputParsersRejectAmbiguityAndDrift(t *testing.T) {
+	goDescriptor := performanceDescriptor(PerformanceGoBenchmark, ".", "BenchmarkThing", PerformanceNSPerOp, "PERF-A")
+	value, err := ParsePerformanceOutput(goDescriptor, PerformanceTarget{}, "BenchmarkThing-8 10 12.500 ns/op 2 B/op 1 allocs/op\n", false)
+	if err != nil || value != "12.5" {
+		t.Fatalf("Go value = %q, %v", value, err)
+	}
+	if _, err := ParsePerformanceOutput(goDescriptor, PerformanceTarget{}, "BenchmarkThing-8 10 12 ns/op\nBenchmarkThing-8 10 13 ns/op\n", false); err == nil {
+		t.Fatal("accepted ambiguous Go output")
+	}
