diff --git a/internal/sprint/performance_discovery.go b/internal/sprint/performance_discovery.go
new file mode 100644
index 0000000000000000000000000000000000000000..1b73459a368fb2a4c890d73064604d702f367f8f
--- /dev/null
+++ b/internal/sprint/performance_discovery.go
@@ -0,0 +1,160 @@
+package sprint
+
+import (
+	"bufio"
+	"fmt"
+	"io/fs"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+)
+
+// PerformanceDescriptorMarker documents the only source-level benchmark
+// mapping accepted by the built-in authoring fallback. It maps a measurement
+// function to requirements-owned target IDs without redefining any target.
+const PerformanceDescriptorMarker = "ultraplan:performance-v1"
+
+// DiscoverPerformanceManifest reads contained Go test files and converts exact
+// descriptor markers into a frozen product manifest. A marker must immediately
+// precede its function declaration:
+//
+//	// ultraplan:performance-v1 go-benchmark-v1 ns/op PERF-001,PERF-002
+//	func BenchmarkThing(b *testing.B) { ... }
+func DiscoverPerformanceManifest(root string, packet PerformanceTargetPacket) (PerformanceBenchmarkManifest, error) {
+	cleanRoot := filepath.Clean(root)
+	info, err := os.Stat(cleanRoot)
+	if err != nil || !info.IsDir() {
+		return PerformanceBenchmarkManifest{}, fmt.Errorf("performance target root is unavailable")
+	}
+	var paths []string
+	err = filepath.WalkDir(cleanRoot, func(path string, entry fs.DirEntry, walkErr error) error {
+		if walkErr != nil {
+			return walkErr
+		}
+		if entry.Type()&os.ModeSymlink != 0 {
+			if entry.IsDir() {
+				return filepath.SkipDir
+			}
+			return nil
+		}
+		if entry.IsDir() {
+			name := entry.Name()
+			if path != cleanRoot && (name == ".git" || name == "vendor" || strings.HasPrefix(name, ".ultraplan")) {
+				return filepath.SkipDir
+			}
+			return nil
+		}
+		if strings.HasSuffix(entry.Name(), "_test.go") {
+			paths = append(paths, path)
+			if len(paths) > 10_000 {
+				return fmt.Errorf("performance benchmark discovery exceeds 10000 test files")
+			}
+		}
+		return nil
+	})
+	if err != nil {
+		return PerformanceBenchmarkManifest{}, fmt.Errorf("discover performance benchmarks: %w", err)
+	}
+	sort.Strings(paths)
+	var descriptors []PerformanceDescriptor
+	for _, path := range paths {
+		found, scanErr := discoverPerformanceFile(cleanRoot, path)
+		if scanErr != nil {
+			return PerformanceBenchmarkManifest{}, scanErr
+		}
+		descriptors = append(descriptors, found...)
+	}
+	sort.Slice(descriptors, func(i, j int) bool { return descriptors[i].OutputIdentity < descriptors[j].OutputIdentity })
+	manifest := PerformanceBenchmarkManifest{SchemaVersion: PerformanceSchemaVersion, PacketDigest: packet.PacketDigest, RunnerVersion: PerformanceRunnerVersion, ParserVersion: PerformanceParserVersion, Descriptors: descriptors}
+	if err := ValidatePerformanceManifest(packet, &manifest); err != nil {
+		return PerformanceBenchmarkManifest{}, err
+	}
+	return manifest, nil
+}
+
+func discoverPerformanceFile(root, path string) ([]PerformanceDescriptor, error) {
+	file, err := os.Open(path)
+	if err != nil {
+		return nil, err
+	}
+	defer file.Close()
+	relDir, err := filepath.Rel(root, filepath.Dir(path))
+	if err != nil || relDir == ".." || strings.HasPrefix(relDir, ".."+string(filepath.Separator)) {
+		return nil, fmt.Errorf("performance benchmark file escapes target root")
+	}
+	pkg := "."
+	if relDir != "." {
+		pkg = "./" + filepath.ToSlash(relDir)
+	}
+	var pending string
+	var descriptors []PerformanceDescriptor
+	scanner := bufio.NewScanner(file)
+	line := 0
+	for scanner.Scan() {
+		line++
+		trimmed := strings.TrimSpace(scanner.Text())
+		if strings.HasPrefix(trimmed, "// "+PerformanceDescriptorMarker+" ") {
+			if pending != "" {
+				return nil, fmt.Errorf("%s:%d: performance descriptor marker has no function", filepath.ToSlash(path), line)
+			}
+			pending = strings.TrimSpace(strings.TrimPrefix(trimmed, "// "+PerformanceDescriptorMarker+" "))
+			continue
+		}
+		if pending == "" {
+			continue
+		}
+		if trimmed == "" || strings.HasPrefix(trimmed, "//") {
+			continue
+		}
+		symbol, ok := performanceFunctionSymbol(trimmed)
+		if !ok {
+			return nil, fmt.Errorf("%s:%d: performance descriptor marker must immediately precede a function", filepath.ToSlash(path), line)
+		}
+		descriptor, parseErr := parsePerformanceDescriptorMarker(pending, pkg, symbol)
+		if parseErr != nil {
+			return nil, fmt.Errorf("%s:%d: %w", filepath.ToSlash(path), line, parseErr)
+		}
+		descriptors = append(descriptors, descriptor)
+		pending = ""
+	}
+	if err := scanner.Err(); err != nil {
+		return nil, err
+	}
+	if pending != "" {
+		return nil, fmt.Errorf("%s: performance descriptor marker has no function", filepath.ToSlash(path))
+	}
+	return descriptors, nil
+}
+
+func performanceFunctionSymbol(line string) (string, bool) {
+	if !strings.HasPrefix(line, "func ") {
+		return "", false
+	}
+	rest := strings.TrimPrefix(line, "func ")
+	at := strings.IndexByte(rest, '(')
+	if at <= 0 {
+		return "", false
+	}
+	symbol := strings.TrimSpace(rest[:at])
+	return symbol, symbol != "" && !strings.ContainsAny(symbol, " \t")
+}
+
+func parsePerformanceDescriptorMarker(marker, pkg, symbol string) (PerformanceDescriptor, error) {
+	fields := strings.Fields(marker)
+	if len(fields) != 3 {
+		return PerformanceDescriptor{}, fmt.Errorf("descriptor marker requires runner, raw unit, and comma-separated target IDs")
+	}
+	descriptor := PerformanceDescriptor{Kind: PerformanceDescriptorKind(fields[0]), Package: pkg, Symbol: symbol, RawUnit: PerformanceUnit(fields[1]), ParserVersion: PerformanceParserVersion}
+	for _, id := range strings.Split(fields[2], ",") {
+		if id == "" || strings.TrimSpace(id) != id {
+			return PerformanceDescriptor{}, fmt.Errorf("descriptor marker contains an invalid target ID")
+		}
+		descriptor.TargetIDs = append(descriptor.TargetIDs, id)
+	}
+	descriptor.OutputIdentity = string(descriptor.Kind) + ":" + descriptor.Package + ":" + descriptor.Symbol + ":" + string(descriptor.RawUnit)
+	if err := ValidatePerformanceDescriptor(descriptor); err != nil {
+		return PerformanceDescriptor{}, err
+	}
+	return descriptor, nil
+}

