+package sprint
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"os"
+	"time"
+
+	pprocess "github.com/Antonio7098/ultraplan-go/internal/platform/process"
+)
+
+const (
+	performanceIsolationFiles    = 200_000
+	performanceIsolationBytes    = int64(2 << 30)
+	performanceIsolationFileSize = int64(32 << 20)
+)
+
+type performanceIsolation struct {
+	workspace pprocess.IsolationWorkspace
+	parent    string
+}
+
+func createPerformanceIsolation(ctx context.Context, source string, protected []string, limits PerformanceLimits) (performanceIsolation, error) {
+	parent, err := os.MkdirTemp("", "ultraplan-performance-")
+	if err != nil {
+		return performanceIsolation{}, fmt.Errorf("create performance isolation parent: %w", err)
+	}
+	copyTimeout := limits.CommandTimeout
+	if copyTimeout <= 0 {
+		copyTimeout = 5 * time.Minute
+	}
+	workspace, err := pprocess.CreateIsolation(ctx, pprocess.IsolationRequest{
+		SourceRoot:     source,
+		ParentDir:      parent,
+		Prefix:         "measurement",
+		ProtectedRoots: append(append([]string(nil), protected...), source),
+		Limits: pprocess.IsolationLimits{
+			MaxFiles:    performanceIsolationFiles,
+			MaxBytes:    performanceIsolationBytes,
+			MaxFileSize: performanceIsolationFileSize,
+			Timeout:     copyTimeout,
+		},
+	})
+	if err != nil {
+		_ = os.Remove(parent)
+		return performanceIsolation{}, fmt.Errorf("create performance isolation: %w", err)
+	}
+	return performanceIsolation{workspace: workspace, parent: parent}, nil
+}
+
+func (i performanceIsolation) runner(delegate pprocess.Runner) pprocess.Runner {
+	return performanceIsolationRunner{workspace: i.workspace, delegate: delegate}
+}
+
+func (i performanceIsolation) assertUnchanged(ctx context.Context) error {
+	changed, err := i.workspace.ChangedPaths(ctx, pprocess.IsolationLimits{
+		MaxFiles:    performanceIsolationFiles,
+		MaxBytes:    performanceIsolationBytes,
+		MaxFileSize: performanceIsolationFileSize,
+		Timeout:     5 * time.Minute,
+	})
+	if err != nil {
+		return fmt.Errorf("verify performance isolation identity: %w", err)
+	}
+	if len(changed) != 0 {
+		return fmt.Errorf("performance commands changed the frozen benchmark workspace")
+	}
+	return nil
+}
+
+func (i performanceIsolation) cleanup() error {
+	cleanup := i.workspace.Cleanup()
+	parentErr := os.Remove(i.parent)
+	if !cleanup.Complete {
+		if cleanup.Error == "" {
+			cleanup.Error = "workspace removal was not proven"
+		}
+		return fmt.Errorf("performance cleanup is uncertain: %s", cleanup.Error)
+	}
+	if parentErr != nil && !errors.Is(parentErr, os.ErrNotExist) {
+		return fmt.Errorf("performance cleanup is uncertain: remove isolation parent: %w", parentErr)
+	}
+	return nil
+}
+
+type performanceIsolationRunner struct {
+	workspace pprocess.IsolationWorkspace
+	delegate  pprocess.Runner
+}
+
+func (r performanceIsolationRunner) Run(ctx context.Context, req pprocess.Request) (pprocess.Result, error) {
+	return r.workspace.Run(ctx, r.delegate, ".", req)
+}

