+)
+
+func TestPerformanceIsolationKeepsCanonicalTargetImmutable(t *testing.T) {
+	source := t.TempDir()
+	canonical := filepath.Join(source, "source.go")
+	if err := os.WriteFile(canonical, []byte("package source\n"), 0o644); err != nil {
+		t.Fatal(err)
+	}
+	isolation, err := createPerformanceIsolation(context.Background(), source, []string{source}, DefaultPerformanceLimits())
+	if err != nil {
+		t.Fatal(err)
+	}
+	runner := isolation.runner(performanceMutatingRunner{})
+	if _, err := runner.Run(context.Background(), pprocess.Request{Executable: "go", Dir: source}); err != nil {
+		t.Fatal(err)
+	}
+	if err := isolation.assertUnchanged(context.Background()); err == nil {
+		t.Fatal("isolated benchmark mutation was not detected")
+	}
+	data, err := os.ReadFile(canonical)
+	if err != nil || string(data) != "package source\n" {
+		t.Fatalf("canonical target changed: %q, %v", data, err)
+	}
+	workspacePath := isolation.workspace.Path
+	if err := isolation.cleanup(); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := os.Stat(workspacePath); !os.IsNotExist(err) {
+		t.Fatalf("isolation workspace remains: %v", err)
+	}
+}
+
+type performanceMutatingRunner struct{}
+
+func (performanceMutatingRunner) Run(_ context.Context, req pprocess.Request) (pprocess.Result, error) {
+	if err := os.WriteFile(filepath.Join(req.Dir, "source.go"), []byte("package changed\n"), 0o644); err != nil {
+		return pprocess.Result{}, err
+	}
+	return pprocess.Result{CleanupComplete: true}, nil
+}

