+package sprint
+
+import (
+	"fmt"
+	"path/filepath"
+	"sort"
+	"strings"
+)
+
+type PerformanceProfileKind string
+
+const (
+	PerformanceProfileCPU        PerformanceProfileKind = "cpu-v1"
+	PerformanceProfileAllocation PerformanceProfileKind = "allocation-v1"
+	PerformanceProfileMemory     PerformanceProfileKind = "memory-v1"
+	PerformanceProfileWall       PerformanceProfileKind = "wall-v1"
+	PerformanceProfileThroughput PerformanceProfileKind = "throughput-v1"
+	PerformanceProfileCount      PerformanceProfileKind = "count-v1"
+)
+
+type PerformanceProfile struct {
+	SchemaVersion  int                    `json:"schema_version"`
+	Cycle          int                    `json:"cycle"`
+	TargetID       string                 `json:"target_id"`
+	Kind           PerformanceProfileKind `json:"kind"`
+	Implementation string                 `json:"implementation"`
+	Digest         string                 `json:"digest"`
+	Bytes          int                    `json:"bytes"`
+	Artifact       PerformanceArtifactRef `json:"artifact"`
+}
+
+type PerformanceHypothesis struct {
+	SchemaVersion int    `json:"schema_version"`
+	Cycle         int    `json:"cycle"`
+	TargetID      string `json:"target_id"`
+	Summary       string `json:"summary"`
+	ProfileDigest string `json:"profile_digest"`
+}
+
+type PerformanceProposalScope struct {
+	SchemaVersion int      `json:"schema_version"`
+	Cycle         int      `json:"cycle"`
+	TargetID      string   `json:"target_id"`
+	Before        string   `json:"before"`
+	Candidate     string   `json:"candidate"`
+	Paths         []string `json:"paths"`
+	ChangedBytes  int64    `json:"changed_bytes"`
+	Allowed       bool     `json:"allowed"`
+	Reason        string   `json:"reason,omitempty"`
+}
+
+type PerformanceApplyJournal struct {
+	SchemaVersion int                    `json:"schema_version"`
+	Cycle         int                    `json:"cycle"`
+	State         string                 `json:"state"`
+	Before        string                 `json:"before"`
+	After         string                 `json:"after,omitempty"`
+	Operations    []RepairApplyOperation `json:"operations"`
+}
+
+func SelectPerformanceMiss(targets []PerformanceTarget, comparisons []PerformanceComparison) (PerformanceTarget, bool) {
+	missed := map[string]bool{}
+	for _, comparison := range comparisons {
+		if comparison.Outcome == PerformanceTargetMissed {
+			missed[comparison.TargetID] = true
+		}
+	}
+	ordered := append([]PerformanceTarget(nil), targets...)
+	sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
+	for _, target := range ordered {
+		if target.Gate == PerformanceRequired && target.Comparator != PerformanceBaseline && missed[target.ID] {
+			return target, true
+		}
+	}
+	return PerformanceTarget{}, false
+}
+
+func PerformanceProfileForUnit(unit PerformanceUnit) (PerformanceProfileKind, error) {
+	switch unit {
+	case PerformanceNSPerOp:
+		return PerformanceProfileCPU, nil
+	case PerformanceBytesPerOp, PerformanceAllocsPerOp:
+		return PerformanceProfileAllocation, nil
+	case PerformanceMiB:
+		return PerformanceProfileMemory, nil
+	case PerformanceMS:
+		return PerformanceProfileWall, nil
+	case PerformanceOpsPerSec:
+		return PerformanceProfileThroughput, nil
+	case PerformanceTasksPerRun:
+		return PerformanceProfileCount, nil
+	default:
+		return "", fmt.Errorf("performance unit %q has no V1 optimization profile", unit)
+	}
+}
+
+func PerformanceStrictImprovement(target PerformanceTarget, before, candidate string) (bool, error) {
+	_, oldValue, err := canonicalPerformanceDecimal(before)
+	if err != nil {
+		return false, err
+	}
+	_, newValue, err := canonicalPerformanceDecimal(candidate)
+	if err != nil {
+		return false, err
+	}
+	switch target.Comparator {
+	case PerformanceLessOrEqual:
+		return newValue.Cmp(oldValue) < 0, nil
+	case PerformanceGreaterOrEqual:
+		return newValue.Cmp(oldValue) > 0, nil
+	default:
+		return false, fmt.Errorf("target %s is not optimizable", target.ID)
+	}
+}
+
+// ValidatePerformanceOptimizationScope applies the production-only V1
+// allowlist to the actual isolated-tree diff, not to runtime-declared paths.
+func ValidatePerformanceOptimizationScope(paths []string, changedBytes int64, limits PerformanceLimits) ([]string, error) {
+	if len(paths) == 0 || len(paths) > limits.ChangedFiles || changedBytes <= 0 || changedBytes > limits.ChangedBytes {
+		return nil, fmt.Errorf("performance proposal exceeds its file or byte limit")
+	}
+	normalized, err := NormalizeRepairPaths(paths)
+	if err != nil || len(normalized) != len(paths) {
+		return nil, fmt.Errorf("performance proposal paths are invalid")
+	}
+	for _, path := range normalized {
+		lower := strings.ToLower(path)
+		if ClassifyRepairPath(path) != RepairPathProduction || strings.HasSuffix(lower, "_test.go") || strings.Contains(lower, "/testdata/") || filepath.Ext(lower) == ".snap" {
+			return nil, fmt.Errorf("performance proposal changed protected path %q", path)
+		}
+	}
+	return normalized, nil
+}
+
+func ValidatePerformanceRegressionSet(selected PerformanceTarget, before, candidate PerformanceMeasurement, alreadyMet []PerformanceTargetResult) error {
+	if !candidate.Qualification.Qualified {
+		return fmt.Errorf("candidate measurement for %s is not qualified", selected.ID)
+	}
+	improved, err := PerformanceStrictImprovement(selected, before.Qualification.Median, candidate.Qualification.Median)
+	if err != nil || !improved {
+		return fmt.Errorf("candidate does not strictly improve %s", selected.ID)
+	}
+	for _, result := range alreadyMet {
+		if result.Target.Gate == PerformanceRequired && result.Comparison.Outcome != PerformanceTargetMet {
+			return fmt.Errorf("candidate regressed required target %s", result.Target.ID)
+		}
+		if result.Target.Gate == PerformanceRequired && !result.FinalQualification.Qualified {
+			return fmt.Errorf("candidate made required target %s inconclusive", result.Target.ID)
+		}
+	}
+	return nil
+}
+
+func ValidatePerformanceApplyJournal(value PerformanceApplyJournal) error {
+	if value.SchemaVersion != PerformanceSchemaVersion || value.Cycle <= 0 || !validFingerprint(value.Before) {
+		return fmt.Errorf("invalid performance apply journal identity")
+	}
+	switch value.State {
+	case "planned", "applying", "applied", "compensated", "uncertain":
+	default:
+		return fmt.Errorf("invalid performance apply journal state")
+	}
+	if value.State == "applied" && !validFingerprint(value.After) {
+		return fmt.Errorf("applied performance journal lacks final identity")
+	}
+	if len(value.Operations) == 0 || len(value.Operations) > MaxPerformanceLimits().ChangedFiles {
+		return fmt.Errorf("invalid performance apply journal operations")
+	}
+	for _, operation := range value.Operations {
+		if ClassifyRepairPath(operation.Path) != RepairPathProduction || !validFingerprint(operation.PreimageDigest) || !validFingerprint(operation.PostimageDigest) || operation.PreimagePath == "" {
+			return fmt.Errorf("invalid performance apply operation")
+		}
+	}
+	return nil
+}

