+package sprint
+
+import (
+	"os"
+	"path/filepath"
+	"testing"
+)
+
+func TestPerformanceOptimizationPureBoundaries(t *testing.T) {
+	targets := []PerformanceTarget{{ID: "PERF-Z", Gate: PerformanceReport, Comparator: PerformanceLessOrEqual}, {ID: "PERF-B", Gate: PerformanceRequired, Comparator: PerformanceLessOrEqual, Unit: PerformanceNSPerOp}, {ID: "PERF-A", Gate: PerformanceRequired, Comparator: PerformanceGreaterOrEqual, Unit: PerformanceOpsPerSec}}
+	selected, ok := SelectPerformanceMiss(targets, []PerformanceComparison{{TargetID: "PERF-B", Outcome: PerformanceTargetMissed}, {TargetID: "PERF-A", Outcome: PerformanceTargetMissed}})
+	if !ok || selected.ID != "PERF-A" {
+		t.Fatalf("selected = %#v, %t", selected, ok)
+	}
+	if kind, _ := PerformanceProfileForUnit(PerformanceBytesPerOp); kind != PerformanceProfileAllocation {
+		t.Fatalf("profile = %s", kind)
+	}
+	if improved, err := PerformanceStrictImprovement(targets[1], "10", "9.99"); err != nil || !improved {
+		t.Fatalf("improved = %t, %v", improved, err)
+	}
+	if improved, err := PerformanceStrictImprovement(targets[1], "10", "10"); err != nil || improved {
+		t.Fatalf("equality improved = %t, %v", improved, err)
+	}
+}
+
+func TestPerformanceOptimizationScopeRejectsAuthorityAndTests(t *testing.T) {
+	limits := DefaultPerformanceLimits()
+	if _, err := ValidatePerformanceOptimizationScope([]string{"internal/sprint/service.go"}, 10, limits); err != nil {
+		t.Fatal(err)
+	}
+	for _, path := range []string{"requirements.md", "internal/sprint/service_test.go", ".git/config", "testdata/golden.json", "go.mod"} {
+		if _, err := ValidatePerformanceOptimizationScope([]string{path}, 10, limits); err == nil {
+			t.Fatalf("accepted protected path %q", path)
+		}
+	}
+}
+
+func TestReconcilePerformanceJournalRestoresDigestBoundPreimage(t *testing.T) {
+	root := t.TempDir()
+	sp := Sprint{Project: "alpha", Slug: "39-performance", Path: filepath.Join(root, "projects", "alpha", "sprints", "39-performance")}
+	target := filepath.Join(root, "target")
+	if err := os.MkdirAll(filepath.Join(target, "internal", "example"), 0o755); err != nil {
+		t.Fatal(err)
+	}
+	path := filepath.Join(target, "internal", "example", "example.go")
+	before, after := []byte("package example\n\nconst value = 1\n"), []byte("package example\n\nconst value = 2\n")
+	if err := os.WriteFile(path, after, 0o644); err != nil {
+		t.Fatal(err)
+	}
+	token := VerificationWriterToken{RunID: "run", OperationalAttemptID: "attempt", FencingGeneration: 1}
+	store := NewPerformanceStore(root, sp).WithWriterFence(func(got VerificationWriterToken) error { return nil })
+	attemptID := "performance-v1-attempt-0123456789abcdef01234567"
+	preimagePath, err := PerformanceCycleRelPath(sp, attemptID, 1, "preimage-000001.bin")
+	if err != nil {
+		t.Fatal(err)
+	}
+	preimageRef, err := store.PublishBytes(preimagePath, "cycle-apply-preimage", before, true, token)
+	if err != nil {
+		t.Fatal(err)
+	}
+	journal := PerformanceApplyJournal{SchemaVersion: PerformanceSchemaVersion, Cycle: 1, State: "applying", Before: fingerprintOf("before-tree"), Operations: []RepairApplyOperation{{Path: "internal/example/example.go", PreimageDigest: preimageRef.Digest, PreimagePath: preimageRef.Path, PostimageDigest: hashBytes(after), Applied: true}}}
+	// The tree fingerprint is separately checked by recovery. This unit isolates
+	// exact file compensation, so bind the journal to the observed restored tree.
+	if err := os.WriteFile(path, before, 0o644); err != nil {
+		t.Fatal(err)
+	}
+	journal.Before, err = targetIdentity(target)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(path, after, 0o644); err != nil {
+		t.Fatal(err)
+	}
+	applied, complete := reconcilePerformanceJournal(store, target, filepath.Dir(preimageRef.Path), &journal)
+	if !applied || !complete || journal.State != "compensated" || !journal.Operations[0].Restored {
+		t.Fatalf("reconciliation = applied %t complete %t journal %#v", applied, complete, journal)
+	}
+	got, err := os.ReadFile(path)
+	if err != nil || string(got) != string(before) {
+		t.Fatalf("restored bytes = %q, %v", got, err)
+	}
+}

