+)
+
+const performanceHardStateBytes = 128 << 20
+const performanceEvidenceScanLimit = 4096
+
+var performanceAttemptID = regexp.MustCompile(`^performance-v1-attempt-[a-f0-9]{24}$`)
+
+type PerformanceStore struct {
+	root   string
+	sprint Sprint
+	fence  func(VerificationWriterToken) error
+	hooks  QAStateHooks
+}
+
+func (store PerformanceStore) ReadJSON(ref PerformanceArtifactRef, value any) error {
+	data, err := store.ReadBytes(ref)
+	if err != nil {
+		return err
+	}
+	return jsonNewStrictDecoder(data)(value)
+}
+
+func (store PerformanceStore) ReadBytes(ref PerformanceArtifactRef) ([]byte, error) {
+	path, err := store.resolve(ref.Path)
+	if err != nil {
+		return nil, err
+	}
+	if err := performanceNoFollow(path, store.sprint.Path); err != nil {
+		return nil, err
+	}
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return nil, err
+	}
+	if len(data) == 0 || len(data) > performanceHardStateBytes || hashBytes(data) != ref.Digest {
+		return nil, fmt.Errorf("performance artifact digest mismatch")
+	}
+	return data, nil
+}
+
+type PerformanceEvidenceRecord struct {
+	AttemptID string `json:"attempt_id"`
+	Name      string `json:"name"`
+	Path      string `json:"path"`
+	Digest    string `json:"digest"`
+	Size      int64  `json:"size_bytes"`
+}
+
+type PerformanceEvidencePage struct {
+	Records    []PerformanceEvidenceRecord `json:"records"`
+	NextCursor string                      `json:"next_cursor,omitempty"`
+}
+
+// EvidencePage performs a bounded, attempt-scoped metadata query. It never
+// returns artifact contents or reconstructs state by walking old attempts.
+func (store PerformanceStore) EvidencePage(attemptID, cursor, filter string, limit int) (PerformanceEvidencePage, error) {
+	if !performanceAttemptID.MatchString(attemptID) {
+		return PerformanceEvidencePage{}, fmt.Errorf("invalid performance attempt ID")
+	}
+	if limit <= 0 || limit > MaxPerformanceLimits().EvidencePageSize {
+		return PerformanceEvidencePage{}, fmt.Errorf("invalid performance evidence page size")
+	}
+	baseRel, _ := PerformanceAttemptRelPath(store.sprint, attemptID, "placeholder")
+	base, err := store.resolve(filepath.Dir(baseRel))
+	if err != nil {
+		return PerformanceEvidencePage{}, err
+	}
+	capacity := limit * 2
+	if capacity > performanceEvidenceScanLimit {
+		capacity = performanceEvidenceScanLimit
+	}
+	names := make([]string, 0, capacity)
+	scanned := 0
+	err = filepath.WalkDir(base, func(path string, entry fs.DirEntry, walkErr error) error {
+		if walkErr != nil {
+			return walkErr
+		}
+		if path == base {
+			return nil
+		}
+		scanned++
+		if scanned > performanceEvidenceScanLimit {
+			return fmt.Errorf("performance evidence scan exceeds %d entries", performanceEvidenceScanLimit)
+		}
+		if entry.Type()&os.ModeSymlink != 0 {
+			return fmt.Errorf("performance evidence contains a symbolic link")
+		}
+		if entry.IsDir() {
+			return nil
+		}
+		if !entry.Type().IsRegular() {
+			return fmt.Errorf("performance evidence contains a non-regular record")
+		}
+		rel, relErr := filepath.Rel(base, path)
+		if relErr != nil {
+			return relErr
+		}
+		name := filepath.ToSlash(rel)
+		if strings.Contains(name, filter) {
+			names = append(names, name)
+		}
+		return nil
+	})
+	if err != nil {
+		return PerformanceEvidencePage{}, err
+	}
+	sort.Strings(names)
+	page := PerformanceEvidencePage{}
+	for _, name := range names {
+		if cursor != "" && name <= cursor {
+			continue
+		}
+		if len(page.Records) == limit {
+			page.NextCursor = page.Records[len(page.Records)-1].Name
+			break
+		}
+		path := filepath.Join(base, filepath.FromSlash(name))
+		info, statErr := os.Lstat(path)
+		

[... bounded excerpt ...]

reshness.PolicyDigest,
+		"execute": state.Freshness.ExecuteDigest, "packet": state.Freshness.PacketDigest,
+		"manifest": state.Freshness.ManifestDigest, "correctness": state.Freshness.CorrectnessDigest,
+		"process_policy": state.Freshness.ProcessPolicyDigest, "environment": state.Freshness.EnvironmentIdentity,
+		"workflow": state.Freshness.WorkflowDigest, "initial_implementation": state.Freshness.InitialImplementation,
+		"final_implementation": state.Freshness.FinalImplementation, "result": state.Freshness.ResultDigest,
+	} {
+		if digest != "" && !validFingerprint(digest) {
+			return fmt.Errorf("performance state has an invalid %s freshness digest", name)
+		}
+	}
+	switch state.Phase {
+	case PerformancePhaseReady, PerformancePhasePreparing, PerformancePhaseBaseline, PerformancePhaseOptimizing, PerformancePhaseFinalizing, PerformancePhaseTerminal, PerformancePhaseStale:
+	default:
+		return fmt.Errorf("invalid performance state phase")
+	}
+	if state.Phase == PerformancePhaseTerminal && !validPerformanceRunOutcome(state.Outcome) {
+		return fmt.Errorf("terminal performance state has an invalid outcome")
+	}
+	if len(state.FreshnessReasons) > 32 || len(state.Blocker) > 512 || len(state.NextAction) > 1024 {
+		return fmt.Errorf("performance state text exceeds its bound")
+	}
+	return nil
+}
+
+func validatePerformanceCounters(counters PerformanceCounters, limits PerformanceLimits) error {
+	if counters.Commands < 0 || counters.Commands > limits.Commands || counters.Warmups < 0 || counters.Warmups > counters.Commands || counters.Samples < 0 || counters.Samples > counters.Commands || counters.OptimizationCycles < 0 || counters.OptimizationCycles > limits.OptimizationCycles || counters.RuntimeAttempts < 0 {
+		return fmt.Errorf("performance counters exceed the persisted attempt limits")
+	}
+	maxRuntimeAttempts := limits.AuthoringAttempts + limits.OptimizationCycles*limits.OptimizationAttempts
+	if counters.RuntimeAttempts > maxRuntimeAttempts {
+		return fmt.Errorf("performance runtime attempts exceed the persisted attempt limits")
+	}
+	return nil
+}
+
+func validatePerformanceStateRef(state PerformanceState, ref PerformanceArtifactRef, name string, required bool) error {
+	if !required && ref.Path == "" && ref.Digest == "" {
+		return nil
+	}
+	want, err := PerformanceAttemptRelPath(Sprint{Project: state.Project, Slug: state.Sprint}, state.AttemptID, name)
+	if err != nil || ref.Path != want || !validFingerprint(ref.Digest) {
+		return fmt.Errorf("performance state has an invalid %s reference", name)
+	}
+	return nil
+}
+
+func validPerformanceRunOutcome(outcome PerformanceRunOutcome) bool {
+	switch outcome {
+	case PerformancePassed, PerformancePassedWithReports, PerformanceTargetMiss, PerformanceBlocked, PerformanceStalled, PerformanceCancelled, PerformanceCleanupUncertain:
+		return true
+	default:
+		return false
+	}
+}
+
+func (store PerformanceStore) checkWriter(token VerificationWriterToken) error {
+	if err := token.Validate(); err != nil {
+		return fmt.Errorf("invalid performance writer: %w", err)
+	}
+	if store.fence == nil {
+		return fmt.Errorf("no verification writer fence is configured")
+	}
+	if err := store.fence(token); err != nil {
+		return fmt.Errorf("performance writer is stale: %w", err)
+	}
+	return nil
+}
+
+func (store PerformanceStore) resolve(rel string) (string, error) {
+	return resolveSprintContained(store.root, store.sprint, rel)
+}
+
+func performanceNoFollow(path, sprintRoot string) error {
+	cleanPath, cleanRoot := filepath.Clean(path), filepath.Clean(sprintRoot)
+	if cleanPath != cleanRoot && !strings.HasPrefix(cleanPath, cleanRoot+string(filepath.Separator)) {
+		return fmt.Errorf("performance path escapes sprint root")
+	}
+	for current := cleanPath; current != cleanRoot; current = filepath.Dir(current) {
+		info, err := os.Lstat(current)
+		if errors.Is(err, fs.ErrNotExist) {
+			continue
+		}
+		if err != nil {
+			return err
+		}
+		if info.Mode()&os.ModeSymlink != 0 {
+			return fmt.Errorf("performance path contains a symbolic link")
+		}
+	}
+	return nil
+}

