index 0000000000000000000000000000000000000000..3c7a5173be07baef08327f68da4cd6f4cdef013e
--- /dev/null
+++ b/internal/sprint/performance_targets.go
@@ -0,0 +1,311 @@
+package sprint
+
+import (
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"fmt"
+	"math/big"
+	"regexp"
+	"sort"
+	"strconv"
+	"strings"
+	"unicode/utf8"
+)
+
+var performanceTargetID = regexp.MustCompile(`^PERF-[A-Z0-9-]+$`)
+var performanceDecimal = regexp.MustCompile(`^-?[0-9]+(?:\.[0-9]+)?$`)
+var performanceHeaders = []string{"ID", "Scenario", "Metric", "Comparator", "Value", "Unit", "Gate", "Samples", "Basis"}
+
+func ParsePerformanceTargets(content string) (PerformanceTargetPacket, []ValidationFinding) {
+	digest := sha256.Sum256([]byte(content))
+	packet := PerformanceTargetPacket{SchemaVersion: PerformanceSchemaVersion, ParserVersion: PerformanceParserVersion, RequirementsDigest: hex.EncodeToString(digest[:])}
+	lines := strings.Split(content, "\n")
+	var findings []ValidationFinding
+	inFence, inComment, found, collecting := false, false, false, false
+	var table [][]string
+	for i, raw := range lines {
+		line := strings.TrimSpace(raw)
+		if inComment {
+			if end := strings.Index(line, "-->"); end >= 0 {
+				line, inComment = strings.TrimSpace(line[end+3:]), false
+			} else {
+				continue
+			}
+		}
+		if start := strings.Index(line, "<!--"); start >= 0 {
+			if end := strings.Index(line[start+4:], "-->"); end < 0 {
+				inComment = true
+			}
+			line = strings.TrimSpace(line[:start])
+		}
+		if strings.HasPrefix(line, "```") || strings.HasPrefix(line, "~~~") {
+			inFence = !inFence
+			continue
+		}
+		if inFence || strings.HasPrefix(line, ">") || strings.HasPrefix(raw, "    ") || strings.HasPrefix(raw, "\t") {
+			continue
+		}
+		if strings.HasPrefix(line, "#") {
+			collecting = false
+			if line == "## Performance Targets" {
+				if found {
+					findings = append(findings, finding("Performance Targets", "", "", "duplicate performance targets section", fmt.Sprintf("line %d: section appears more than once", i+1), "Keep exactly one Performance Targets section."))
+				}
+				found, collecting, table = true, true, nil
+			}
+			continue
+		}
+		if !collecting {
+			continue
+		}
+		if line == "" && len(table) == 0 {
+			continue
+		}
+		if !strings.HasPrefix(line, "|") {
+			if len(table) == 0 {
