+)
+
+const validPerformanceTable = `## Performance Targets
+
+| ID | Scenario | Metric | Comparator | Value | Unit | Gate | Samples | Basis |
+| --- | --- | --- | --- | ---: | --- | --- | ---: | --- |
+| PERF-Z | pkg benchmark Z | latency | <= | 0010.5000 | ns/op | required | 5 | absolute |
+| PERF-A | package JSON A | throughput change | >= | 15 | % | required | 10 | baseline |
+| PERF-REPORT | package JSON report | current memory | baseline | - | MiB | report | 6 | current |
+`
+
+func TestParsePerformanceTargetsNormalizesAndBinds(t *testing.T) {
+	packet, findings := ParsePerformanceTargets(validPerformanceTable)
+	if len(findings) != 0 {
+		t.Fatalf("findings = %#v", findings)
+	}
+	if got := []string{packet.Targets[0].ID, packet.Targets[1].ID, packet.Targets[2].ID}; !reflect.DeepEqual(got, []string{"PERF-A", "PERF-REPORT", "PERF-Z"}) {
+		t.Fatalf("order = %v", got)
+	}
+	if packet.Targets[2].Value != "10.5" || len(packet.PacketDigest) != 64 || len(packet.RequirementsDigest) != 64 {
+		t.Fatalf("packet = %#v", packet)
+	}
+	again, _ := ParsePerformanceTargets(validPerformanceTable)
+	if !reflect.DeepEqual(packet, again) {
+		t.Fatal("same bytes did not produce the same packet")
+	}
+	changed, _ := ParsePerformanceTargets(validPerformanceTable + "\n")
+	if changed.RequirementsDigest == packet.RequirementsDigest || changed.PacketDigest == packet.PacketDigest {
+		t.Fatal("requirements change did not invalidate packet")
+	}
+}
+
+func TestPerformanceTargetTableRejectsInvalidContracts(t *testing.T) {
+	tests := []string{
+		"| PERF-A | s | m | < | 1 | ns/op | required | 5 | absolute |",
+		"| perf-a | s | m | <= | 1 | ns/op | required | 5 | absolute |",
+		"| PERF-A | s | m | <= | NaN | ns/op | required | 5 | absolute |",
+		"| PERF-A | s | m | <= | 1 | seconds | required | 5 | absolute |",
+		"| PERF-A | s | m | <= | 1 | ns/op | required | 4 | absolute |",
+		"| PERF-A | s | m | baseline | - | ns/op | required | 5 | current |",
+		"| PERF-A | s | m | <= | 1 | ns/op | required | 5 | baseline |",
+	}
+	base := "## Performance Targets\n\n| ID | Scenario | Metric | Comparator | Value | Unit | Gate | Samples | Basis |\n| --- | --- | --- | --- | ---: | --- | --- | ---: | --- |\n"
+	for _, row := range tests {
+		if _, findings := ParsePerformanceTargets(base + row + "\n"); len(findings) == 0 {
+			t.Fatalf("accepted invalid row %q", row)
+		}
+	}
+}
+
+func TestPerformancePseudoSectionsAreIgnored(t *testing.T) {
+	for _, content := range []string{"```md\n" + validPerformanceTable + "```\n", "> " + validPerformanceTable, "<!--\n" + validPerformanceTable + "-->\n"} {
+		packet, findings := ParsePerformanceTargets(content)
+		if len(findings) != 0 || len(packet.Targets) != 0 {
+			t.Fatalf("pseudo section parsed: %#v %#v", packet, findings)
+		}
+	}
+}
+
+func TestPerformancePolicyAndRequirementsMustAgree(t *testing.T) {
+	requirements := "## Sprint Goal\nx\n## Required Outputs\nx\n## Acceptance Criteria\nx\n## Non-Goals\nx\n## Constraints\nx\n## Dependencies\nx\n## Review Expectations\nx\n" + validPerformanceTable
+	if findings := ValidateRequirementsContentWithPolicy(requirements, project.PerformancePolicy{Mode: project.PerformanceEnabled}); len(findings) != 0 {
+		t.Fatalf("enabled findings = %#v", findings)
+	}
+	if findings := ValidateRequirementsContentWithPolicy(requirements, project.PerformancePolicy{Mode: project.PerformanceDisabled}); len(findings) == 0 {
+		t.Fatal("disabled policy accepted targets")
+	}
+}
+
+func TestPerformanceComparisonAndOutcomePrecedence(t *testing.T) {
+	abs := PerformanceTarget{ID: "PERF-A", Comparator: PerformanceLessOrEqual, Value: "10", Unit: PerformanceMS, Gate: PerformanceRequired, Basis: PerformanceAbsolute}
+	comparison, err := ComparePerformanceTarget(abs, "", "10.0", true, false)
+	if err != nil || comparison.Outcome != PerformanceTargetMet {
+		t.Fatalf("absolute equality = %#v, %v", comparison, err)
+	}
+	rel := PerformanceTarget{ID: "PERF-B", Comparator: PerformanceLessOrEqual, Value: "-10", Unit: PerformancePercent, Gate: PerformanceRequired, Basis: PerformanceRelative}
+	comparison, err = ComparePerformanceTarget(rel, "100", "90", true, false)
+	if err != nil || comparison.Outcome != PerformanceTargetMet || comparison.ComparedValue != "-10" {
+		t.Fatalf("relative equality = %#v, %v", comparison, err)
+	}
+	comparison, _ = ComparePerformanceTarget(rel, "0", "1", true, false)
+	if comparison.Outcome != PerformanceTargetInconclusive {
+		t.Fatalf("zero baseline = %#v", comparison)
+	}
+	if got := DerivePerformanceRunOutcome([]PerformanceTargetOutcome{PerformanceTargetMissed}, false, true, false, false); got != PerformanceCleanupUncertain {
+		t.Fatalf("precedence = %q", got)
+	}
+}
+
+func TestPerformanceLimitsRejectZeroNonFiniteAndHardMaximumViolations(t *testing.T) {
+	if err := ValidatePerformanceLimits(DefaultPerformanceLimits()); err != nil {
+		t.Fatal(err)
+	}
+	lower := DefaultPerformanceLimits()
+	lower.Commands = 64
+	lower.CVPercent = 2.5
+	if err := ValidatePerformanceLimits(lower); err != nil {
+		t.Fatalf("lower limits rejected: %v", err)
+	}
+	tests := []struct {
+		name   string
+		mutate func(*PerformanceLimits)
+	}{
+		{"zero commands", func(v *PerformanceLimits) { v.Commands = 0 }},
+		{"too many commands", func(v *PerformanceLimits) { v.Commands = MaxPerformanceLimits().Commands + 1 }},
+		{"negative changed bytes", func(v *PerformanceLimits) { v.ChangedBytes = -1 }},
+		{"zero timeout", func(v *PerformanceLimits) { v.CommandTimeout = 0 }},
+		{"non-finite cv", func(v *PerformanceLimits) { v.CVPercent = math.Inf(1) }},
+	}
+	for _, test := range tests {
+		t.Run(test.name, func(t *testing.T) {
+			limits := DefaultPerformanceLimits()
+			test.mutate(&limits)
+			if err := ValidatePerformanceLimits(limits); err == nil {
+				t.Fatalf("invalid limits accepted: %#v", limits)
+			}
+		})
+	}
+}

